def minimumCost(nums: List[int]) -> int:
    """
    Find the minimum cost to make all elements equal to a palindromic number.

    The cost of changing all elements to value y is sum(|nums[i] - y|).
    We need to find a palindromic number y (1 <= y < 10^9) that minimizes this cost.

    Key insight: The optimal y (without the palindrome constraint) is the median of nums.
    With the palindrome constraint, we need to check palindromic numbers near the median.
    """
    n = len(nums)
    nums_sorted = sorted(nums)

    # The optimal value without constraint is the median
    # For even n, any value between nums_sorted[n//2 - 1] and nums_sorted[n//2] is optimal
    # For odd n, the median is nums_sorted[n//2]

    # We need to find palindromic numbers near the median range
    # Let's find the median value(s)
    if n % 2 == 1:
        median = nums_sorted[n // 2]
        candidates = [median]
    else:
        lo = nums_sorted[n // 2 - 1]
        hi = nums_sorted[n // 2]
        # The optimal range is [lo, hi], so we should check palindromic numbers in this range and nearby
        candidates = []

    # Generate palindromic numbers near the median
    # We need to be careful: the optimal palindrome might be a bit away if there are no palindromes near the median

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    def get_nearby_palindromes(center: int, count: int = 20) -> List[int]:
        """Get palindromic numbers near center."""
        pals = set()
        # Check numbers around center
        for d in range(0, 200000):  # Search in a window
            if center - d >= 1:
                if is_palindrome(center - d):
                    pals.add(center - d)
                    if len(pals) >= count:
                        break
            if center + d <= 10**9:
                if is_palindrome(center + d):
                    pals.add(center + d)
                    if len(pals) >= count:
                        break
        return list(pals)

    # Better approach: generate palindromic numbers by constructing them
    # A palindromic number can be generated from its first half
    def generate_palindromes_near(target: int) -> List[int]:
        """Generate palindromic numbers near target."""
        pals = set()
        t = str(target)
        length = len(t)

        # Generate palindromes of the same length and neighboring lengths
        for L in [length - 1, length, length + 1]:
            if L < 1 or L > 10:  # 10^9 has 10 digits, max palindrome < 10^9 is 999999999 (9 digits)
                continue
            half_len = (L + 1) // 2

            if half_len == 1:
                # Single digit: 1-9
                for d in range(1, 10):
                    val = d
                    if 1 <= val < 10**9:
                        pals.add(val)
            else:
                # The first half determines the palindrome
                half_start = 10 ** (half_len - 1)
                half_end = 10 ** half_len - 1

                # We want halves that produce palindromes near target
                # The first half of target
                target_half = int(t[:half_len])

                # Search in a reasonable range around target_half
                search_lo = max(half_start, target_half - 100000)
                search_hi = min(half_end, target_half + 100000)

                for h in range(search_lo, search_hi + 1):
                    s = str(h)
                    if L % 2 == 0:
                        pal_str = s + s[::-1]
                    else:
                        pal_str = s + s[-2::-1]
                    try:
                        pal = int(pal_str)
                    except:
                        continue
                    if 1 <= pal < 10**9:
                        pals.add(pal)

        return list(pals)

    # Compute cost for a given value y
    def cost(y: int) -> int:
        total = 0
        for num in nums_sorted:
            total += abs(num - y)
        return total

    # Get candidate palindromic numbers
    # Use the median as the center
    if n % 2 == 1:
        center = nums_sorted[n // 2]
    else:
        center = (nums_sorted[n // 2 - 1] + nums_sorted[n // 2]) // 2

    candidates = generate_palindromes_near(center)

    # Also add a few more by direct search
    for d in range(0, 10000):
        v = center - d
        if v >= 1 and is_palindrome(v):
            candidates.append(v)
        v = center + d
        if v < 10**9 and is_palindrome(v):
            candidates.append(v)

    if not candidates:
        # Fallback: find the closest palindrome
        candidates = [1]

    min_cost = float('inf')
    for cand in candidates:
        if cand < 1 or cand >= 10**9:
            continue
        c = cost(cand)
        if c < min_cost:
            min_cost = c

    return min_cost
