def maximumJumps(nums: List[int], target: int) -> int:
    n = len(nums)
    if n < 2:
        return -1

    # dp[i] = maximum number of jumps to reach index i
    # Initialize to -1 (unreachable)
    dp = [-1] * n
    dp[0] = 0

    # For each index j, check all previous indices i < j
    # if nums[j] - nums[i] is within [-target, target]
    for j in range(1, n):
        for i in range(j):
            diff = nums[j] - nums[i]
            if -target <= diff <= target:
                if dp[i] != -1:
                    if dp[j] == -1:
                        dp[j] = dp[i] + 1
                    else:
                        dp[j] = max(dp[j], dp[i] + 1)

    return dp[n - 1]
