def findPrimePairs(n: int):
    if n < 4:
        return []

    # Sieve of Eratosthenes up to n
    is_prime = [True] * (n + 1)
    is_prime[0] = False
    if n >= 1:
        is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False

    result = []
    # x ranges from 1 to n//2 (since x <= y and x + y == n)
    for x in range(2, n // 2 + 1):
        y = n - x
        if x <= y and is_prime[x] and is_prime[y]:
            result.append([x, y])

    return result
